class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = sum(1 for x in nums if x == k)
        best_gain = 0
        for v in set(nums):
            if v == k:
                continue
            cur = 0
            best = 0
            for x in nums:
                if x == v:
                    cur += 1
                elif x == k:
                    cur -= 1
                    if cur < 0:
                        cur = 0
                if cur > best:
                    best = cur
            if best > best_gain:
                best_gain = best
        return total_k + best_gain
