class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        cnt_k = sum(1 for a in nums if a == k)
        best_gain = 0
        for v in set(nums):
            if v == k:
                continue
            cur = 0
            local_best = 0
            for a in nums:
                if a == v:
                    s = 1
                elif a == k:
                    s = -1
                else:
                    s = 0
                cur = max(cur + s, s)
                if cur > local_best:
                    local_best = cur
            if local_best > best_gain:
                best_gain = local_best
        return cnt_k + best_gain

