import json
from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    if draw(st.booleans()):
        # small value range to force duplicates and collisions with k
        vals = st.integers(1, 5)
        k = draw(st.integers(1, 5))
    else:
        # full value range, scaled down in length only
        vals = st.integers(1, 50)
        k = draw(st.integers(1, 50))
    mode = draw(st.integers(0, 4))
    nums = draw(st.lists(vals, min_size=n, max_size=n))
    if mode == 1:
        nums = [k] * n  # all equal to k
    elif mode == 2:
        nums = sorted(nums)  # sorted
    elif mode == 3:
        nums = sorted(nums, reverse=True)  # reverse sorted
    elif mode == 4:
        nums = [nums[0]] * n  # all equal to some value
    return json.dumps(nums) + "\n" + json.dumps(k) + "\n"

def validate(inp):
    try:
        lines = [l for l in inp.split("\n") if l.strip() != ""]
        if len(lines) != 2:
            return False
        nums = json.loads(lines[0])
        k = json.loads(lines[1])
    except Exception:
        return False
    if not isinstance(nums, list) or not isinstance(k, int) or isinstance(k, bool):
        return False
    n = len(nums)
    if not (1 <= n <= 10**5):
        return False
    if not all(isinstance(v, int) and not isinstance(v, bool) and 1 <= v <= 50 for v in nums):
        return False
    if not (1 <= k <= 50):
        return False
    return True

def ref(inp):
    lines = [l for l in inp.split("\n") if l.strip() != ""]
    nums = json.loads(lines[0])
    k = json.loads(lines[1])
    n = len(nums)
    best = 0
    # Literal brute force: every subarray [i..j], every integer x in a range
    # that certainly contains all useful shifts (k - v for v in 1..50, and 0).
    for i in range(n):
        for j in range(i, n):
            for x in range(-100, 101):
                arr = list(nums)
                for t in range(i, j + 1):
                    arr[t] += x
                f = sum(1 for v in arr if v == k)
                if f > best:
                    best = f
    return json.dumps(best)
