    elif mode == "reverse":
        nums = sorted(draw(st.lists(st.integers(1, 50), min_size=n, max_size=n)), reverse=True)
    elif mode == "small":
        nums = draw(st.lists(st.integers(1, 4), min_size=n, max_size=n))
    else:
